const tone=s=>statusTone(s);
export async function loadOperatingSystem(){const d=await api('/api/platform/admin/operating-system');return d.operatingSystem||{};}
export async function renderOperations(){
 const box=$?.('#view-operations');if(!box)return;box.innerHTML='<div class="workspace-loading">Loading administrative operation journal…</div>';
 try{const os=await loadOperatingSystem();box.innerHTML=`<div class="operating-surface"><header class="control-hero"><div><span class="eyebrow">COMMAND · OPERATIONS</span><h1 class="title">Administrative Operations</h1><p class="sub">Every platform operation remains owned by its canonical service. This surface only projects state and evidence.</p></div><span class="pill ${tone(os.health)}">${esc(os.health||'UNKNOWN')}</span></header><section class="os-grid four">${[['In flight',os.platform?.operationsInFlight,'system-health'],['Live products',os.platform?.liveProducts,'product-health'],['Pending verification',os.platform?.pendingVerification,'verification'],['Active missions',os.platform?.activeMissions,'missions']].map(([l,v,w])=>`<button class="os-stat card" data-os-open="${esc(w)}"><span>${esc(l)}</span><strong>${esc(v??'UNAVAILABLE')}</strong><small>OPEN</small></button>`).join('')}</section><section class="card section"><header class="section-head"><div><span class="eyebrow">OPERATION JOURNAL</span><h2>Recent administrative operations</h2><p class="sub">Requested → executing → verifying → succeeded / recovered is owned by the administrative operation authority.</p></div></header><div class="os-operation-list">${(os.operations||[]).map(o=>`<button class="os-operation" data-operation-id="${esc(o.id)}"><span class="os-operation-code">${esc(o.action_code||'ADMIN ACTION')}</span><b>${esc(o.resource_type||'resource')}${o.resource_id?` #${esc(o.resource_id)}`:''}</b><span class="pill ${tone(o.status)}">${esc(o.status||'UNKNOWN')}</span><time>${esc(o.updated_at||o.created_at||'—')}</time></button>`).join('')||'<div class="empty">No administrative operations are currently recorded.</div>'}</div></section><section class="card section"><header class="section-head"><div><span class="eyebrow">PLATFORM HISTORY</span><h2>Administrative evidence</h2></div></header><div class="os-history-list">${(os.history||[]).map(h=>`<article class="os-history"><span>${esc(h.action||'Administrative event')}</span><b>${esc(h.resource_type||'resource')}${h.resource_id?` #${esc(h.resource_id)}`:''}</b><time>${esc(h.created_at||'—')}</time></article>`).join('')||'<div class="empty">No administrative history is available.</div>'}</div></section></div>`;
 box.querySelectorAll('[data-os-open]').forEach(b=>b.addEventListener('click',()=>navigate?.(b.dataset.osOpen)));
 box.querySelectorAll('[data-operation-id]').forEach(b=>b.addEventListener('click',()=>{const o=(os.operations||[]).find(x=>String(x.id)===String(b.dataset.operationId));if(!o)return;openAdminDrawer({title:o.operation_key||`Operation #${o.id}`,eyebrow:'ADMINISTRATIVE OPERATION',summary:'Canonical operation state is authoritative; this drawer is a read-only projection.',facts:[{label:'Action',value:o.action_code},{label:'Resource',value:`${o.resource_type||'resource'} ${o.resource_id?`#${o.resource_id}`:''}`},{label:'Status',value:o.status},{label:'Scope',value:o.scope_key||'Platform'},{label:'Updated',value:o.updated_at||o.created_at||'—'}],actionLabel:'OPEN SYSTEM HEALTH',onAction:()=>navigate?.('system-health')})}));
 }catch(e){box.innerHTML=`<section class="card section error-state"><div class="eyebrow">AUTHORITY UNAVAILABLE</div><h2>Administrative operation authority unavailable</h2><p class="sub">No empty operation state was substituted.</p><div class="notice">${esc(e.message||'Unable to read administrative operations.')}</div></section>`}
}

export async function renderActionMatrix(){
 const box=$?.('#view-action-matrix');if(!box)return;box.innerHTML='<div class="workspace-loading">Loading canonical Action Registry projection…</div>';
 try{const d=await api('/api/platform/admin/action-matrix');const rows=d.actionMatrix||[];const grouped=new Map();for(const x of rows){if(!grouped.has(x.domain))grouped.set(x.domain,[]);grouped.get(x.domain).push(x)}box.innerHTML=`<div class="operating-surface"><header class="control-hero"><div><span class="eyebrow">COMMAND · CANONICAL ACTION MATRIX</span><h1 class="title">Canonical Action Matrix</h1><p class="sub">A read-only projection of the existing Action Registry and Action Service Map. The Control Plane does not execute these actions itself.</p></div><span class="pill ok">${rows.length} CANONICAL ACTIONS</span></header><section class="card section"><div class="notice"><b>Authority boundary</b><br>Each action remains owned by its canonical domain. This matrix tells the Super Admin what exists, who owns it, where it routes, and where to continue the work.</div></section><div class="action-matrix-grid">${[...grouped.entries()].map(([domain,items])=>`<section class="card section action-matrix-group"><header class="section-head"><div><span class="eyebrow">${esc(domain.replaceAll('_',' ').toUpperCase())}</span><h2>${esc(items[0]?.authority||domain)}</h2></div><span class="pill neutral">${items.length}</span></header><div class="action-matrix-table"><div class="action-matrix-head"><span>ACTION</span><span>ROUTE</span><span>CONTROL</span><span>WORKSPACE</span></div>${items.map(x=>`<article class="action-matrix-row"><div><b>${esc(x.label)}</b><small>${esc(x.code)}</small></div><span>${esc(x.routeKind||'—')}</span><span>${x.confirmation?'CONFIRMATION':'STANDARD'} · ${x.safeByDefault?'SAFE':'GUARDED'}</span><button class="btn muted" data-action-workspace="${esc(x.workspace)}">OPEN</button></article>`).join('')}</div></section>`).join('')}</div></div>`;box.querySelectorAll('[data-action-workspace]').forEach(b=>b.addEventListener('click',()=>navigate?.(b.dataset.actionWorkspace)))}catch(e){box.innerHTML=`<section class="card section error-state"><h2>Canonical Action Registry unavailable</h2><div class="notice">${esc(e.message||'Unable to load Action Registry projection.')}</div></section>`}
}

export async function renderReleaseCenter(){
 const box=$?.('#view-release-center');if(!box)return;box.innerHTML='<div class="workspace-loading">Loading release lifecycle…</div>';
 try{const os=await loadOperatingSystem();const releases=os.releases||[];box.innerHTML=`<div class="operating-surface"><header class="control-hero"><div><span class="eyebrow">RELEASE</span><h1 class="title">Release Center</h1><p class="sub">A single projection of governed product versions. Product Release Lifecycle remains authoritative.</p></div><button class="btn primary" data-release-open="product-publisher">OPEN PRODUCT FACTORY</button></header><section class="release-os-flow"><span>DRAFT</span><i>→</i><span>VALIDATED</span><i>→</i><span>AUTHORIZED</span><i>→</i><span>PUBLISHED</span><i>→</i><span>VERIFIED</span><i>→</i><span>LIVE</span></section><section class="card section"><header class="section-head"><div><span class="eyebrow">RELEASE LEDGER</span><h2>Recent product versions</h2></div></header><div class="table-wrap"><table class="table"><thead><tr><th>Country</th><th>Version</th><th>Stage</th><th>Updated</th><th>Work</th></tr></thead><tbody>${releases.map(r=>`<tr><td><b>${esc(r.country_code||'—')}</b></td><td>v${esc(r.version||'—')}</td><td><span class="pill ${tone(r.stage)}">${esc(r.stage||'UNKNOWN')}</span></td><td>${esc(r.updated_at||'—')}</td><td><button class="btn muted" data-release-open="product-publisher">OPEN</button></td></tr>`).join('')||'<tr><td colspan="5" class="empty">No product release records are available.</td></tr>'}</tbody></table></div></section></div>`;box.querySelectorAll('[data-release-open]').forEach(b=>b.addEventListener('click',()=>navigate?.(b.dataset.releaseOpen)))}catch(e){box.innerHTML=`<section class="card section error-state"><h2>Release authority unavailable</h2><div class="notice">${esc(e.message||'Unable to read release lifecycle.')}</div></section>`}
}

export async function renderDependencyImpact(){
 const box=$('#view-product-dependency-impact');if(!box)return;box.innerHTML=`<div class="operating-surface"><header class="control-hero"><div><span class="eyebrow">RELEASE · DEPENDENCY IMPACT</span><h1 class="title">Dependency Impact</h1><p class="sub">Inspect the canonical dependency graph before release promotion. Product Dependency Impact remains the owning projection; this workspace does not calculate or store a second graph.</p></div><span class="pill neutral">READ ONLY</span></header><section class="card section"><div class="notice"><b>How to use this surface</b><br>Select a product version in Product Factory, then open its Dependency Impact view. The existing canonical dependency service evaluates depends-on, used-by, blocks, affects, enables and verification relationships.</div><div class="actions"><button class="btn primary" id="openDependencyFactory">OPEN PRODUCT FACTORY</button><button class="btn muted" id="openReleaseCenterFromImpact">OPEN RELEASE CENTER</button></div></section><section class="os-grid three"><article class="card"><span class="eyebrow">AUTHORITY</span><h2>Product Dependency Impact</h2><p class="sub">Canonical dependency projection</p></article><article class="card"><span class="eyebrow">BOUNDARY</span><h2>READ ONLY</h2><p class="sub">No dependency state is created here.</p></article><article class="card"><span class="eyebrow">PROMOTION</span><h2>GUARDED</h2><p class="sub">Release authority owns promotion decisions.</p></article></section></div>`;$('#openDependencyFactory')?.addEventListener('click',()=>navigate('product-publisher'));$('#openReleaseCenterFromImpact')?.addEventListener('click',()=>navigate('release-center'));
}

export async function renderLaunchCenter(){
 const box=$?.('#view-launch-center');if(!box)return;box.innerHTML='<div class="workspace-loading">Loading the governed launch journey…</div>';
 try{
  const [os,cc]=await Promise.all([loadOperatingSystem(),api('/api/platform/admin/command-center')]);
  const live=(os.releases||[]).filter(r=>r.active);
  const surface=cc.surface||{}, next=cc.next||cc.now||{};
  const stages=['PRODUCT SCOPE','COUNTRY FOUNDATION','PRODUCT DEFINITION','RELEASE','VERIFY','LAUNCH','CUSTOMER','MISSION','EXECUTE','VERIFY EFFECT','OUTCOME','RECOVER','LEARN'];
  const current=next.actionLabel||next.action||'START PRODUCT WORKSPACE';
  const reason=next.reason||'Move the product one governed step forward.';
  const actionKey=next.actionKey||'product-publisher';
  box.innerHTML=`<div class="operating-surface"><header class="control-hero"><div><span class="eyebrow">LAUNCH · ONE CURRENT ACTION</span><h1 class="title">Launch Journey</h1><p class="sub">One controlled path from product preparation to a verified mission outcome. Each domain authority remains canonical; this surface only chooses the next place to continue.</p></div><span class="pill ${tone(os.health)}">${esc(os.health||'UNKNOWN')}</span></header>
  <section class="card section current-action-card"><div class="section-head"><div><span class="eyebrow">CURRENT ACTION</span><h2>${esc(current)}</h2><p class="sub">${esc(reason)}</p></div><button class="btn primary" data-launch-action="${esc(actionKey)}">CONTINUE</button></div><div class="notice"><b>Safety:</b> the action is rechecked by its canonical authority before mutation. No launch, customer, mission or execution state is inferred from an empty projection.</div></section>
  <section class="card section"><div class="section-head"><div><span class="eyebrow">PROVING LOOP</span><h2>One journey, explicit stages</h2><p class="sub">The UI exposes the journey without presenting every possible operation at once.</p></div><span class="pill neutral">${live.length?'LIVE PRODUCT PRESENT':'TEST PRODUCT NOT YET LIVE'}</span></div><div class="release-os-flow">${stages.map((s,i)=>`<span>${i+1}. ${esc(s)}</span>${i<stages.length-1?'<i>→</i>':''}`).join('')}</div></section>
  <section class="card section"><div class="notice"><b>Production boundary</b><br>Real external execution requires an approved provider, capability contract, policy, verification and recovery path. A product is not considered proven until a real mission reaches outcome and recovery evidence.</div></section></div>`;
  box.querySelector('[data-launch-action]')?.addEventListener('click',()=>navigate?.(actionKey));
 }catch(e){box.innerHTML=`<section class="card section error-state"><h2>Launch journey unavailable</h2><div class="notice">${esc(e.message||'Unable to read launch journey.')}</div></section>`}
}

export function setSafeMode(enabled){state.safeMode=Boolean(enabled);localStorage.setItem('onmission_super_admin_safe_mode',state.safeMode?'1':'0');return state.safeMode}
export function readSafeMode(){if(state.safeMode===undefined)state.safeMode=localStorage.getItem('onmission_super_admin_safe_mode')!=='0';return Boolean(state.safeMode)}
void ADMIN_WORKSPACES;

async function refreshProductionEvents(){const msg=document.getElementById('productionMsg');const rows=document.getElementById('productionRows');const companyId=Number(document.getElementById('productionCompanyId')?.value||0)||0;if(!companyId){if(msg)msg.textContent='Company ID required';return;}try{const r=await api(`/api/platform/admin/agentic-control/production/events?companyId=${encodeURIComponent(companyId)}&limit=50`);const events=Array.isArray(r?.events)?r.events:[];if(rows)rows.innerHTML=events.map(x=>`<tr><td>${esc(x.event_type||'—')}</td><td>${esc(x.mission_id||'—')}</td><td>${esc(x.action_code||'—')}</td><td>${esc(x.pilot_id||'—')}</td><td>${esc(x.production_mode||'—')}</td><td>${esc(x.outcome_event_id||'—')}</td><td>${esc(x.occurred_at||'—')}</td></tr>`).join('')||'<tr><td colspan="7" class="empty">No production execution events recorded.</td></tr>';}catch(e){if(msg)msg.textContent=String(e?.message||e);}}
async function checkProductionReadiness(){const msg=document.getElementById('productionMsg');const result=document.getElementById('productionResult');const checks=document.getElementById('productionChecks');const companyId=Number(document.getElementById('productionCompanyId')?.value||0)||0;const missionId=Number(document.getElementById('productionMissionId')?.value||0)||0;const action=String(document.getElementById('productionActionCode')?.value||'').trim();if(!companyId||!missionId||!action){if(msg)msg.textContent='Company, mission and action are required';return;}try{const r=await api(`/api/platform/admin/agentic-control/production/readiness?companyId=${encodeURIComponent(companyId)}&missionId=${encodeURIComponent(missionId)}&actionCode=${encodeURIComponent(action)}`);const rd=r?.readiness||{};if(result)result.textContent=rd.ready?'PRODUCTION READY — canonical authorization remains required at execution time.':'PRODUCTION BLOCKED — inspect the failed readiness checks.';if(checks)checks.innerHTML=(rd.checks||[]).map(c=>`<div class="notice"><b>${esc(c.code||'CHECK')}</b> · ${c.ok?'PASS':'BLOCKED'}${c.details?` · ${esc(JSON.stringify(c.details))}`:''}</div>`).join('')||'<div class="mini">No readiness checks returned.</div>';await refreshProductionEvents();}catch(e){if(msg)msg.textContent=String(e?.message||e);}}
export async function renderAgenticControl(){
 const box=$?.('#view-agentic-control');if(!box)return;box.innerHTML='<div class="workspace-loading">Loading Agentic Control Plane…</div>';
 try{
  const d=await api('/api/platform/admin/agentic-control');const c=d.control||{};const decisions=d.decisions||[];const outcomes=d.outcomes||[];const profiles=await api('/api/platform/admin/agentic-control/profiles?limit=25');const executorProfiles=profiles.executorProfiles||[];const organizationProfiles=profiles.organizationProfiles||[];const semantic=d.semantic||{};const semanticStatus=semantic.status||{};const semanticSummary=semantic.summary||{};const recalibration=d.recalibration||{};const recalibrationStatus=recalibration.status||{};let providerCapabilities=[];try{providerCapabilities=(await api('/api/platform/admin/agentic-control/providers?limit=50')).capabilities||[]}catch{};let autonomyPolicies=[];try{autonomyPolicies=(await api('/api/platform/admin/agentic-control/autonomy/policies?limit=100')).policies||[]}catch{}
  const modeOptions=['DISABLED','RECOMMEND_ONLY','PREPARE_ONLY','CONTROLLED_EXECUTION'];
  const semanticState=semanticStatus.enabled?'READY':'UNAVAILABLE';
  const semanticTone=semanticStatus.enabled?'ok':'warn';
  box.innerHTML=`<div class="operating-surface"><header class="control-hero"><div><span class="eyebrow">GOVERN · AGENTIC CONTROL PLANE</span><h1 class="title">Agentic Control</h1><p class="sub">Audit the agent as a governed intelligence layer. Canonical mission truth, authorization and action execution remain outside this control surface.</p></div><span class="pill ${c.executionEnabled?'warn':'ok'}">${esc(c.executionEnabled?'CONTROLLED EXECUTION':'SAFE / NON-EXECUTING')}</span></header>
  <section class="os-grid four"><article class="card os-stat"><span>MODE</span><strong>${esc(c.mode||'UNKNOWN')}</strong><small>GOVERNED</small></article><article class="card os-stat"><span>AUTONOMY</span><strong>L${esc(c.autonomyLevel??'—')}</strong><small>POLICY LEVEL</small></article><article class="card os-stat"><span>DECISIONS</span><strong>${decisions.length}</strong><small>RECENT</small></article><article class="card os-stat"><span>OUTCOMES</span><strong>${outcomes.length}</strong><small>RECENT</small></article></section>
  <section class="card section semantic-runtime-card"><header class="section-head"><div><span class="eyebrow">AGENT INFRASTRUCTURE</span><h2>Semantic Runtime</h2><p class="sub">Application-level verification of Workers AI and Vectorize. This surface never grants execution authority.</p></div><div class="actions"><span id="semanticRuntimePill" class="pill ${semanticTone}">${esc(semanticState)}</span><button class="btn muted" id="semanticRuntimeVerify">VERIFY PROVIDERS</button></div></header><div class="os-grid four semantic-runtime-grid"><article class="card os-stat"><span>WORKERS AI</span><strong>${esc(semanticStatus.embeddingProvider?'CONFIGURED':'MISSING')}</strong><small>${esc(semanticStatus.embeddingModel||'—')}</small></article><article class="card os-stat"><span>VECTORIZE</span><strong>${esc(semanticStatus.vectorProvider?'CONFIGURED':'MISSING')}</strong><small>${esc(semanticStatus.dimensions||'—')} DIMENSIONS · COSINE</small></article><article class="card os-stat"><span>SEMANTIC DOCS</span><strong>${esc(semanticSummary.totalDocuments??0)}</strong><small>${esc(semanticSummary.indexedDocuments??0)} INDEXED · ${esc(semanticSummary.pendingDocuments??0)} PENDING</small></article><article class="card os-stat"><span>TENANTS</span><strong>${esc(semanticSummary.tenantCount??0)}</strong><small>ISOLATED NAMESPACES</small></article></div><div class="notice"><b>Safety boundary.</b> Retrieval is advisory only. Current canonical truth and authorization remain authoritative. No provider verification writes vectors, mission state, policy or agent execution state.</div><div id="semanticRuntimeResult" class="mini" aria-live="polite">${semanticSummary.lastIndexedAt?`Last indexed: ${esc(semanticSummary.lastIndexedAt)}`:'No semantic memory has been indexed yet.'}</div></section>
  <section class="card section"><header class="section-head"><div><span class="eyebrow">AGENT LEARNING</span><h2>Recalibration</h2><p class="sub">Derived reliability measurements from recorded agent outcomes. Calibration is advisory and never changes mission truth, authorization or policy.</p></div><div class="actions"><span id="recalibrationPill" class="pill ${recalibrationStatus.lastRun?.status==='COMPLETED'?'ok':'neutral'}">${esc(recalibrationStatus.lastRun?.status||'NOT RUN')}</span><button class="btn muted" id="recalibrationRun">RUN RECALIBRATION</button></div></header><div class="os-grid four"><article class="card os-stat"><span>PENDING</span><strong id="recalibrationPending">${esc(recalibrationStatus.pendingObservations??0)}</strong><small>UNSCORED OUTCOMES</small></article><article class="card os-stat"><span>PROFILES</span><strong>${esc(recalibration.profiles?.length??0)}</strong><small>DERIVED PROFILES</small></article><article class="card os-stat"><span>MIN SAMPLE</span><strong>5</strong><small>BEFORE DEFERENCE SIGNAL</small></article><article class="card os-stat"><span>VERSION</span><strong>CALIBRATION</strong><small>CALIBRATION CONTRACT</small></article></div><div id="recalibrationResult" class="mini" aria-live="polite">${esc(recalibrationStatus.lastRun?.completedAt?`Last run ${recalibrationStatus.lastRun.completedAt}`:'No recalibration run recorded yet.')} Calibration is advisory only; insufficient samples remain explicitly insufficient.</div><div class="table-wrap"><table class="table"><thead><tr><th>Scope</th><th>Signal</th><th>Known</th><th>Accuracy</th><th>Calibration Error</th><th>Deference</th></tr></thead><tbody>${(recalibration.profiles||[]).map(x=>`<tr><td><b>${esc(x.scopeType||'—')}</b><div class="mini">${esc(x.scopeKey||'—')}</div></td><td>${esc(x.signalCode||'—')}</td><td>${esc(x.knownCount??0)} / ${esc(x.sampleCount??0)}</td><td>${x.accuracy==null?'—':`${Math.round(Number(x.accuracy)*100)}%`}</td><td>${x.calibrationError==null?'—':`${Math.round(Number(x.calibrationError)*100)}%`}</td><td><span class="pill ${x.deferenceState==='TRUSTED'?'ok':x.deferenceState==='DEFER'?'warn':'neutral'}">${esc(x.deferenceState||'INSUFFICIENT_DATA')}</span></td></tr>`).join('')||'<tr><td colspan="6" class="empty">No calibration profiles recorded.</td></tr>'}</tbody></table></div></section>
  <section class="card section"><header class="section-head"><div><span class="eyebrow">AGENT INTELLIGENCE</span><h2>Mission Planner</h2><p class="sub">Situation → intent → canonical alignment → advisory memory → candidate actions → plan → risk → confidence → recommended next action. Planning is read-only and never executes a mission.</p></div><div class="actions"><span id="plannerPill" class="pill neutral">READY FOR MISSION</span></div></header><div class="publisher-scope-grid"><label class="field"><span>Mission ID</span><input id="plannerMissionId" class="input" inputmode="numeric" placeholder="Enter mission ID" /></label><label class="field"><span>Optional intent / goal</span><input id="plannerGoal" class="input" maxlength="300" placeholder="What should the mission accomplish next?" /></label><label class="field"><span>Candidate limit</span><select id="plannerLimit" class="input"><option value="4">4</option><option value="8" selected>8</option><option value="12">12</option></select></label></div><div class="actions"><button class="btn primary" id="plannerRun">GENERATE PLAN</button><span id="plannerMsg" class="mini"></span></div><div id="plannerResult" class="mini" aria-live="polite">No plan generated. The planner will re-read canonical mission truth and canonical action readiness before producing a recommendation.</div><div id="plannerSummary" class="table-wrap"></div><div class="notice"><b>Planner boundary.</b> Learned calibration and semantic memory can affect advisory confidence only. They cannot create truth, authorize actions, bypass canonical action decisions, or execute mutations. Every later execution must revalidate canonical truth, authorization and state.</div></section>
  <section class="card section"><header class="section-head"><div><span class="eyebrow">CUSTOMER PILOT</span><h2>German Customer Pilot</h2><p class="sub">A governed proving ground for real customer operations. Controlled execution is impossible unless the pilot is ACTIVE, readiness is clear, the mission is enrolled and the action is explicitly allowlisted.</p></div><span class="pill neutral">CURRENT</span></header><div class="publisher-scope-grid"><label class="field"><span>Company ID</span><input id="pilotCompanyId" class="input" inputmode="numeric" placeholder="Customer company ID" /></label><label class="field"><span>Country</span><input id="pilotCountry" class="input" value="DE" maxlength="2" /></label><label class="field"><span>Sector</span><select id="pilotSector" class="input"><option value="logistics">logistics</option><option value="cleaning">cleaning</option><option value="general">general</option></select></label><label class="field"><span>Operating mode</span><select id="pilotMode" class="input"><option value="RECOMMEND_ONLY">RECOMMEND_ONLY</option><option value="PREPARE_ONLY">PREPARE_ONLY</option><option value="CONTROLLED_EXECUTION">CONTROLLED_EXECUTION</option></select></label><label class="field"><span>Pilot name</span><input id="pilotName" class="input" maxlength="160" placeholder="Customer pilot" /></label><label class="field"><span>Approved actions</span><input id="pilotActions" class="input" maxlength="500" placeholder="confirm_arrival, start_operation" /></label><label class="field"><span>Start (UTC)</span><input id="pilotStart" class="input" type="datetime-local" /></label><label class="field"><span>End (UTC)</span><input id="pilotEnd" class="input" type="datetime-local" /></label></div><div class="actions"><button class="btn primary" id="pilotCreate">CREATE PILOT</button><button class="btn muted" id="pilotRefresh">REFRESH PILOTS</button><span id="pilotMsg" class="mini"></span></div><div id="pilotResult" class="mini">No pilot loaded. Creating a pilot never activates it; readiness and Super Admin step-up remain required.</div><div class="table-wrap"><table class="table"><thead><tr><th>Customer</th><th>Scope</th><th>Mode</th><th>Status</th><th>Actions</th><th>Updated</th></tr></thead><tbody id="pilotRows"><tr><td colspan="6" class="empty">No customer pilots loaded.</td></tr></tbody></table></div><div class="notice"><b>Pilot safety boundary.</b> Germany is the first launch jurisdiction, but the pilot model is country/sector scoped and reusable globally. The pilot layer never creates mission truth or bypasses authorization. High-impact and irreversible actions remain human-authorized. Missions must be explicitly enrolled before controlled agent execution.</div></section>
  <section class="card section"><header class="section-head"><div><span class="eyebrow">AGENT LEARNING</span><h2>Outcome / Learning Loop</h2><p class="sub">Recorded outcomes are converted into bounded advisory signals. Learning can influence recommendation ordering only; it never changes truth, authorization, policy or execution permission.</p></div><div class="actions"><span class="pill neutral">CURRENT</span><button class="btn muted" id="learningRun">RUN LEARNING</button></div></header><div class="os-grid four"><article class="card os-stat"><span>PENDING</span><strong id="learningPending">—</strong><small>OUTCOMES TO LEARN</small></article><article class="card os-stat"><span>PROFILES</span><strong id="learningProfiles">—</strong><small>ACTION LEARNING PROFILES</small></article><article class="card os-stat"><span>MIN SAMPLE</span><strong>5</strong><small>BEFORE LEARNING STATE</small></article><article class="card os-stat"><span>BOUNDARY</span><strong>ADVISORY</strong><small>NO AUTHORIZATION INFERENCE</small></article></div><div id="learningResult" class="mini" aria-live="polite">Learning is derived from recorded outcomes and explicit outcome resolutions. UNKNOWN outcomes are never silently treated as success.</div><div class="notice"><b>Learning boundary.</b> Learned weights are bounded advisory ranking signals. They cannot activate autonomy, authorize an action, change canonical mission truth, or override a newer canonical state.</div></section>
  <section class="card section"><header class="section-head"><div><span class="eyebrow">EXTERNAL EXECUTION</span><h2>Provider Integrations</h2><p class="sub">Governed adapters connect canonical actions to approved external systems. Provider configuration never becomes mission truth or authorization.</p></div><span class="pill neutral">CURRENT</span></header><div class="table-wrap"><table class="table"><thead><tr><th>Provider</th><th>Capability</th><th>Action</th><th>Adapter</th><th>Verification</th><th>Status</th></tr></thead><tbody>${providerCapabilities.map(x=>`<tr><td><b>${esc(x.provider_name||x.provider_code||'—')}</b><div class="mini">${esc(x.provider_code||'—')}</div></td><td>${esc(x.capability_code||'—')}</td><td>${esc(x.action_code||'—')}</td><td>${esc(x.adapter_type||'—')}</td><td>${Number(x.verification_required)===1?'REQUIRED':'OPTIONAL'}</td><td><span class="pill ${Number(x.active)===1&&['approved','configured'].includes(String(x.contract_status))?'ok':'warn'}">${Number(x.active)===1?esc(String(x.contract_status||'ACTIVE').toUpperCase()):'INACTIVE'}</span></td></tr>`).join('')||'<tr><td colspan="6" class="empty">No provider execution capabilities configured. External execution remains unavailable until a provider, policy and capability contract are approved.</td></tr>'}</tbody></table></div><div class="notice"><b>Provider boundary.</b> Only approved provider capabilities can be selected. Credentials are referenced through runtime bindings, never stored in mission data. Dispatch uses idempotency, bounded timeouts, HTTPS-only endpoints and explicit verification; UNKNOWN never becomes success.</div></section>
  <section class="card section" data-contract-version="11.16.0" data-pilot-contract-version="11.17.0"><header class="section-head"><div><span class="eyebrow">CONTROLLED AUTONOMY</span><h2>Action Autonomy Policy</h2><p class="sub">Autonomy is evaluated per action and scoped by company, country and sector. The effective ceiling is the lowest applicable safety boundary; calibration confidence never grants permission.</p></div><span class="pill neutral">CURRENT</span></header><div class="table-wrap"><table class="table"><thead><tr><th>Action</th><th>Scope</th><th>Max Level</th><th>Execution</th><th>Human Approval</th><th>Provider</th><th>Recovery</th></tr></thead><tbody>${autonomyPolicies.map(x=>`<tr><td><b>${esc(x.action_code||'—')}</b></td><td>${esc(x.scope_type||'—')} · ${esc(x.scope_key||'—')}</td><td>L${esc(x.max_autonomy_level??'—')}</td><td>${Number(x.execution_enabled)===1?'ENABLED':'DISABLED'}</td><td>${Number(x.human_approval_required)===1?'REQUIRED':'NOT REQUIRED'}</td><td>${Number(x.provider_required)===1?'REQUIRED':'OPTIONAL'}</td><td>${esc(x.recovery_policy||'—')}</td></tr>`).join('')||'<tr><td colspan="7" class="empty">No database autonomy overrides configured. Built-in risk defaults remain safe ceilings, and tenant execution remains disabled until explicitly configured.</td></tr>'}</tbody></table></div><div class="notice"><b>Controlled autonomy boundary.</b> Global agent control, tenant autonomy, action policy, jurisdiction policy, canonical readiness, authorization, provider capability and verification must all agree. High-impact and irreversible actions remain human-authorized. A policy can only reduce safety, never elevate a canonical authority.</div></section>
  <section class="card section"><header class="section-head"><div><span class="eyebrow">SAFETY GOVERNANCE</span><h2>Runtime posture</h2><p class="sub">Changes require Super Admin step-up and are audited. The default posture remains non-executing until deliberately enabled.</p></div><span class="pill neutral">v${esc(c.version||'—')} · tenant-scoped autonomy</span></header><div class="publisher-scope-grid"><label class="field"><span>Mode</span><select id="agenticMode" class="input">${modeOptions.map(x=>`<option value="${x}" ${x===c.mode?'selected':''}>${x.replaceAll('_',' ')}</option>`).join('')}</select></label><label class="field"><span>Autonomy level</span><select id="agenticAutonomy" class="input">${[0,1,2,3,4,5].map(x=>`<option value="${x}" ${Number(x)===Number(c.autonomyLevel)?'selected':''}>L${x} — ${['Disabled','Recommend','Prepare','Low-risk execution','Operational execution','Human-governed high impact'][x]}</option>`).join('')}</select></label><label class="field"><span>Policy version</span><input id="agenticPolicy" class="input" maxlength="80" value="${esc(c.policyVersion||'11.08.1')}" /></label><label class="field"><span>Execution</span><select id="agenticExecution" class="input"><option value="0" ${!c.executionEnabled?'selected':''}>Disabled</option><option value="1" ${c.executionEnabled?'selected':''}>Enabled</option></select></label></div><label class="field"><span>Control / kill-switch reason</span><input id="agenticReason" class="input" maxlength="500" value="${esc(c.killSwitchReason||'')}" placeholder="Required when disabling the agent" /></label><div class="actions"><button class="btn primary" id="agenticSave">SAVE GOVERNANCE</button><button class="btn muted" id="agenticDisable">EMERGENCY DISABLE</button><span id="agenticMsg" class="mini"></span></div></section>
  <section class="card section"><header class="section-head"><div><span class="eyebrow">DECISION AUDIT</span><h2>Recent agent decisions</h2><p class="sub">Every execution-capable decision must exist here before the canonical action service will accept it.</p></div><span class="pill neutral">APPEND ONLY</span></header><div class="table-wrap"><table class="table"><thead><tr><th>Decision</th><th>Mission</th><th>Action</th><th>Risk</th><th>Confidence</th><th>Policy</th><th>Created</th></tr></thead><tbody>${decisions.map(x=>`<tr><td><b>${esc(x.decision_id)}</b><div class="mini">${esc(x.agent_id||'agent')}</div></td><td>${esc(x.mission_id||'—')}</td><td>${esc(x.action_code)}</td><td><span class="pill ${tone(x.risk_class)}">${esc(x.risk_class)}</span></td><td>${esc(x.confidence)}</td><td>${esc(x.policy_version||'—')}</td><td>${esc(x.created_at||'—')}</td></tr>`).join('')||'<tr><td colspan="7" class="empty">No agent decisions recorded.</td></tr>'}</tbody></table></div></section>
  <section class="card section"><header class="section-head"><div><span class="eyebrow">AGENT MEMORY</span><h2>Derived outcome profiles</h2><p class="sub">Historical execution patterns are derived from the append-only outcome ledger. They are decision-support memory, never authorization or operational truth.</p></div><span class="pill neutral">DERIVED ONLY</span></header><div class="table-wrap"><table class="table"><thead><tr><th>Scope</th><th>Observed</th><th>Known</th><th>Favorable</th><th>Adverse</th><th>Blocked</th><th>Unknown</th><th>Updated</th></tr></thead><tbody>${organizationProfiles.map(x=>`<tr><td><b>Organization #${esc(x.companyId)}</b><div class="mini">${esc(x.company_name||'Tenant')}</div></td><td>${esc(x.observedOutcomes)}</td><td>${esc(x.knownOutcomes)}</td><td>${esc(x.favorableOutcomes)}${x.favorableRate==null?'':` · ${Math.round(x.favorableRate*100)}%`}</td><td>${esc(x.adverseOutcomes)}</td><td>${esc(x.blockedOutcomes)}</td><td>${esc(x.unknownOutcomes)}</td><td>${esc(x.updatedAt||'—')}</td></tr>`).join('')||'<tr><td colspan="8" class="empty">No organization outcome profiles recorded.</td></tr>'}</tbody></table></div><div class="table-wrap"><table class="table"><thead><tr><th>Executor</th><th>Tenant</th><th>Observed</th><th>Known</th><th>Favorable</th><th>Adverse</th><th>Blocked</th><th>Unknown</th></tr></thead><tbody>${executorProfiles.map(x=>`<tr><td><b>${esc(x.executorName||`Executor #${x.executorId}`)}</b></td><td>${esc(x.companyId)}</td><td>${esc(x.observedOutcomes)}</td><td>${esc(x.knownOutcomes)}</td><td>${esc(x.favorableOutcomes)}${x.favorableRate==null?'':` · ${Math.round(x.favorableRate*100)}%`}</td><td>${esc(x.adverseOutcomes)}</td><td>${esc(x.blockedOutcomes)}</td><td>${esc(x.unknownOutcomes)}</td></tr>`).join('')||'<tr><td colspan="8" class="empty">No executor outcome profiles recorded.</td></tr>'}</tbody></table></div></section>
  <section class="card section"><header class="section-head"><div><span class="eyebrow">OUTCOME AUDIT</span><h2>Decision → execution → operational outcome</h2><p class="sub">Execution success is not treated as operational success. UNKNOWN remains UNKNOWN.</p></div><span class="pill neutral">HASH CHAINED</span></header><div class="table-wrap"><table class="table"><thead><tr><th>Decision</th><th>Action</th><th>Execution</th><th>Outcome</th><th>Confidence</th><th>State</th><th>Occurred</th></tr></thead><tbody>${outcomes.map(x=>`<tr><td><b>${esc(x.decision_id)}</b></td><td>${esc(x.action_code)}</td><td>${esc(x.execution_status)}</td><td><span class="pill ${tone(x.outcome_code)}">${esc(x.outcome_code)}</span></td><td>${esc(x.outcome_confidence)}</td><td>${esc(x.state_version_before??'—')} → ${esc(x.state_version_after??'—')}</td><td>${esc(x.occurred_at||'—')}</td></tr>`).join('')||'<tr><td colspan="7" class="empty">No agent outcomes recorded.</td></tr>'}</tbody></table></div></section>
  <section class="card section"><header class="section-head"><div><span class="eyebrow">PRODUCTION EXECUTION</span><h2>Production Mission Boundary</h2><p class="sub">12.0 production execution is evidence-driven and pilot-scoped. Readiness is evaluated from canonical mission truth; production events record evidence only and never become a second authority.</p></div><span class="pill neutral">12.0.1</span></header><div class="publisher-scope-grid"><label class="field"><span>Company ID</span><input id="productionCompanyId" class="input" inputmode="numeric" placeholder="Customer company ID"></label><label class="field"><span>Mission ID</span><input id="productionMissionId" class="input" inputmode="numeric" placeholder="Mission ID"></label><label class="field"><span>Action</span><input id="productionActionCode" class="input" maxlength="120" placeholder="confirm_arrival"></label></div><div class="actions"><button class="btn primary" id="productionReadiness">CHECK READINESS</button><button class="btn muted" id="productionRefresh">REFRESH EVENTS</button><span id="productionMsg" class="mini"></span></div><div id="productionResult" class="mini">No production readiness check performed. A production boundary requires an ACTIVE controlled-execution pilot, enrolled mission and explicit action allowlists.</div><div id="productionChecks" class="table-wrap"></div><div class="table-wrap"><table class="table"><thead><tr><th>Event</th><th>Mission</th><th>Action</th><th>Pilot</th><th>Mode</th><th>Outcome</th><th>Occurred</th></tr></thead><tbody id="productionRows"><tr><td colspan="7" class="empty">No production execution events loaded.</td></tr></tbody></table></div><div class="notice"><b>Production boundary.</b> Readiness is a gate, not permission. Canonical authorization and canonical action execution remain authoritative. Production evidence is append-only; outcome/learning remains derived and advisory.</div></section><section class="card section"><header class="section-head"><div><span class="eyebrow">GOVERNED EXECUTION</span><h2>Execution Attempts</h2><p class="sub">Agent execution is permitted only through the canonical action boundary. Every attempt is recorded, idempotent, revalidated against fresh truth, and remains unverified until the verification layer confirms the external effect.</p></div><span class="pill neutral">CURRENT</span></header><div id="agentExecutionSummary" class="mini">No governed execution attempts recorded.</div><div class="table-wrap"><table class="table"><thead><tr><th>Mission</th><th>Action</th><th>Status</th><th>Verification</th><th>Decision</th><th>Created</th></tr></thead><tbody id="agentExecutionRows"><tr><td colspan="6" class="empty">No governed execution attempts recorded.</td></tr></tbody></table></div><div class="notice"><b>Execution boundary.</b> The agent can request only actions that are current canonical recommendations. Fresh truth, canonical authorization, governance and autonomy are rechecked immediately before dispatch. High-impact and irreversible actions remain human-authorized.</div></section>
  <section class="card section"><header class="section-head"><div><span class="eyebrow">RECOVERY &amp; RECONCILIATION</span><h2>Execution Recovery Events</h2><p class="sub">The recovery engine re-reads canonical truth before deciding what happened. UNKNOWN is never replayed blindly; unresolved external effects remain explicit.</p></div><span class="pill neutral">CURRENT</span></header><div id="agentRecoverySummary" class="mini">No recovery events recorded.</div><div class="table-wrap"><table class="table"><thead><tr><th>Mission</th><th>Attempt</th><th>Event</th><th>Recovery State</th><th>Strategy</th><th>Created</th></tr></thead><tbody id="agentRecoveryRows"><tr><td colspan="6" class="empty">No recovery events recorded.</td></tr></tbody></table></div><div class="notice"><b>Safety boundary.</b> Recovery is evidence-driven. The system verifies canonical state first, does not retry UNKNOWN automatically, and escalates when the real-world effect cannot be verified from authoritative data.</div></section>
  <section class="card section"><div class="notice"><b>Non-negotiable boundary.</b> The agent has no direct SQL mutation authority. It cannot create canonical mission truth, bypass authorization, execute high-impact or irreversible actions autonomously, or turn predictions into facts. Super Admin controls only the agentic runtime posture.</div></section></div>`;
  const refreshCustomerPilots=async()=>{const body=$('#pilotRows');try{const x=await api('/api/platform/admin/agentic-control/pilots?limit=50');const rows=x.pilots||[];if(body)body.innerHTML=rows.map(p=>'<tr><td><b>'+esc(p.name||'—')+'</b><div class=\"mini\">'+esc(p.pilotId||'—')+'</div></td><td>'+esc(p.companyId)+' · '+esc(p.countryCode)+'/'+esc(p.sectorCode)+'</td><td>'+esc(p.operatingMode)+'</td><td><span class=\"pill '+(p.status==='ACTIVE'?'ok':p.status==='PAUSED'?'warn':'neutral')+'\">'+esc(p.status)+'</span></td><td>'+esc((p.approvedActionCodes||[]).join(', ')||'—')+'</td><td>'+esc(p.updatedAt||'—')+'</td></tr>').join('')||'<tr><td colspan=\"6\" class=\"empty\">No customer pilots configured.</td></tr>';if(rows.length&&$('#pilotResult'))$('#pilotResult').textContent=rows.length+' pilot profile'+(rows.length===1?'':'s')+' · activation remains gated by readiness and step-up.';}catch(e){if(body)body.innerHTML='<tr><td colspan=\"6\" class=\"empty\">Pilot authority unavailable; no fallback data substituted.</td></tr>';if($('#pilotResult'))$('#pilotResult').textContent=e.message||'Customer pilot authority unavailable.';}};
  $('#pilotRefresh')?.addEventListener('click',refreshCustomerPilots);
  $('#pilotCreate')?.addEventListener('click',async()=>{const msg=$('#pilotMsg');try{const companyId=Number($('#pilotCompanyId')?.value||0);const countryCode=String($('#pilotCountry')?.value||'DE').trim().toUpperCase();const sectorCode=String($('#pilotSector')?.value||'logistics');const operatingMode=String($('#pilotMode')?.value||'RECOMMEND_ONLY');const name=String($('#pilotName')?.value||'').trim();const startAt=String($('#pilotStart')?.value||'').trim();const endAt=String($('#pilotEnd')?.value||'').trim();const approvedActionCodes=String($('#pilotActions')?.value||'').split(',').map(x=>x.trim()).filter(Boolean);if(!companyId){msg.textContent='Company ID required.';return;}msg.textContent='CREATING…';await api('/api/platform/admin/agentic-control/pilots',{method:'POST',body:{companyId,countryCode,sectorCode,operatingMode,name,approvedActionCodes,startAt:startAt?new Date(startAt).toISOString():null,endAt:endAt?new Date(endAt).toISOString():null}});msg.textContent='Pilot created in DRAFT.';await refreshCustomerPilots();}catch(e){msg.textContent=e.message||'Pilot creation blocked.';}});
  await refreshCustomerPilots();
  const recalibrationRun=$('#recalibrationRun');
  recalibrationRun?.addEventListener('click',async()=>{const pill=$('#recalibrationPill');const pending=$('#recalibrationPending');const result=$('#recalibrationResult');try{recalibrationRun.disabled=true;recalibrationRun.textContent='RUNNING…';if(pill){pill.textContent='RUNNING';pill.className='pill neutral';}const x=await api('/api/platform/admin/agentic-control/recalibration/run',{method:'POST',body:{limit:200}});const r=x.result||{};if(pending)pending.textContent='0';if(pill){pill.textContent=r.status||'UNKNOWN';pill.className=`pill ${r.status==='COMPLETED'?'ok':'warn'}`;}result.textContent=`Processed ${r.processedEvents??0} outcomes · ${r.newObservations??0} new observations · ${r.profilesUpdated??0} profiles updated · minimum sample ${r.minimumSampleSize??5}.`;await renderAgenticControl();}catch(e){if(pill){pill.textContent='BLOCKED';pill.className='pill warn';}result.textContent=e.message||'Recalibration unavailable.';}finally{recalibrationRun.disabled=false;recalibrationRun.textContent='RUN RECALIBRATION';}});
  $('#learningRun')?.addEventListener('click',async()=>{const btn=$('#learningRun');const result=$('#learningResult');try{btn.disabled=true;btn.textContent='RUNNING…';const x=await api('/api/platform/admin/agentic-control/learning/run',{method:'POST',body:{limit:200}});const r=x.result||{};result.textContent=`Processed ${r.processedEvents??0} outcomes · ${r.newObservations??0} learning observations · ${r.profilesUpdated??0} profiles updated · ${r.resolvedUnknowns??0} previously unknown outcomes resolved.`;await renderAgenticControl();}catch(e){result.textContent=e.message||'Learning loop unavailable.';}finally{btn.disabled=false;btn.textContent='RUN LEARNING';}});
  const verifyButton=$('#semanticRuntimeVerify');
  verifyButton?.addEventListener('click',async()=>{const pill=$('#semanticRuntimePill');const result=$('#semanticRuntimeResult');try{verifyButton.disabled=true;verifyButton.textContent='VERIFYING…';if(pill)pill.textContent='CHECKING';if(pill)pill.className='pill neutral';result.textContent='Testing Workers AI embedding and Vectorize query reachability…';const v=await api('/api/platform/admin/agentic-control/semantic/verify');const x=v.verification||{};if(pill){pill.textContent=x.state||'UNKNOWN';pill.className=`pill ${x.healthy?'ok':x.state==='UNAVAILABLE'?'warn':'warn'}`;}const ai=x.checks?.workersAI||{};const vector=x.checks?.vectorize||{};result.textContent=`Workers AI: ${ai.ok?'READY':'NOT READY'} · Vectorize: ${vector.ok?'REACHABLE':'NOT READY'} · ${x.durationMs??0} ms · ${x.checkedAt||'—'}`;}catch(e){if(pill){pill.textContent='UNAVAILABLE';pill.className='pill warn';}result.textContent=e.message||'Semantic runtime verification failed.';}finally{verifyButton.disabled=false;verifyButton.textContent='VERIFY PROVIDERS';}});
  $('#plannerRun')?.addEventListener('click',async()=>{const missionId=Number($('#plannerMissionId')?.value||0);const goal=String($('#plannerGoal')?.value||'').trim();const limit=Number($('#plannerLimit')?.value||8);const pill=$('#plannerPill');const msg=$('#plannerMsg');const result=$('#plannerResult');const summary=$('#plannerSummary');if(!missionId){if(pill){pill.textContent='MISSION ID REQUIRED';pill.className='pill warn';}msg.textContent='Enter a mission ID.';return;}try{const button=$('#plannerRun');if(button){button.disabled=true;button.textContent='PLANNING…';}if(pill){pill.textContent='READING CANONICAL STATE';pill.className='pill neutral';}msg.textContent='';result.textContent='Building situation, alignment and candidate actions…';summary.innerHTML='';const x=await api(`/api/agent/planner/missions/${missionId}`,{method:'POST',body:{goal,candidateLimit:limit}});const p=x.plan||{};const r=p.recommendedNextAction||null;if(pill){pill.textContent=r?.actionCode?(r.recommendationState||'RECOMMEND').toUpperCase():'DEFER';pill.className=r?.state==='READY'?'pill ok':'pill warn';}result.textContent=`${p.intent?.goal||'No intent'} · confidence ${p.confidence?.level||'LOW'} (${Math.round(Number(p.confidence?.score||0)*100)}%) · policy ${p.risk?.policyGate?.state||'DEFER'}.`;summary.innerHTML=`<table class="table"><thead><tr><th>Action</th><th>State</th><th>Risk</th><th>Advisory Weight</th><th>Deference</th><th>Score</th></tr></thead><tbody>${(p.candidates||[]).map(c=>`<tr><td><b>${esc(c.label||c.actionCode)}</b><div class="mini">${esc(c.actionCode)}</div></td><td><span class="pill ${c.state==='READY'?'ok':c.state==='WAITING'?'neutral':'warn'}">${esc(c.state)}</span></td><td>${esc(c.riskClass||'—')}${c.humanApprovalRequired?' · HUMAN APPROVAL':''}</td><td>${esc(c.advisoryWeight??'—')}</td><td>${esc(c.deferenceState||'—')}</td><td>${esc(c.score??'—')}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">No canonical candidates returned.</td></tr>'}</tbody></table>`;}catch(e){if(pill){pill.textContent='UNAVAILABLE';pill.className='pill warn';}msg.textContent=e.message||'Planner unavailable.';result.textContent='No advisory plan was substituted for missing canonical authority.';}finally{const button=$('#plannerRun');if(button){button.disabled=false;button.textContent='GENERATE PLAN';}}});
  const save=async(modeOverride=null,executionOverride=null)=>{const msg=$('#agenticMsg');try{msg.textContent='Saving…';const mode=modeOverride||$('#agenticMode').value;const autonomy=Number($('#agenticAutonomy').value);const execution=executionOverride==null?$('#agenticExecution').value==='1':executionOverride;const result=await api('/api/platform/admin/agentic-control/config',{method:'POST',body:{mode,autonomyLevel:autonomy,executionEnabled:execution,policyVersion:$('#agenticPolicy').value.trim(),killSwitchReason:$('#agenticReason').value.trim()}});msg.textContent=`Saved v${result.control.version}.`;await renderAgenticControl();}catch(e){msg.textContent=e.message||'Governance change blocked.'}};
  $('#agenticSave')?.addEventListener('click',()=>save());
  $('#agenticDisable')?.addEventListener('click',()=>{if(!confirm('Disable agent execution now? This keeps audit/context available and blocks agent mutation execution.'))return;$('#agenticReason').value='Emergency containment by Super Admin';save('DISABLED',false)});
  await refreshAgentExecutionAttempts();
  await refreshAgentRecoveryEvents();
 }catch(e){box.innerHTML=`<section class="card section error-state"><div class="eyebrow">AGENTIC AUTHORITY UNAVAILABLE</div><h2>The Agentic Control Plane could not be read.</h2><p class="sub">No agent state was inferred or substituted.</p><div class="notice">${esc(e.message||'Agentic control unavailable')}</div></section>`}
}

async function refreshAgentRecoveryEvents(){try{const x=await api('/api/platform/admin/agentic-control/recovery?limit=25');const rows=x.events||[];const body=$('#agentRecoveryRows');const summary=$('#agentRecoverySummary');if(summary)summary.textContent=rows.length?`${rows.length} recovery/reconciliation event${rows.length===1?'':'s'} · canonical truth remains authoritative.`:'No recovery events recorded.';if(body)body.innerHTML=rows.map(a=>`<tr><td>${esc(a.mission_id??'—')}</td><td>${esc(a.attempt_id||'—')}</td><td>${esc(a.event_type||'—')}</td><td><span class="pill ${['RECOVERED'].includes(a.recovery_state)?'ok':['ESCALATE_HUMAN','RETRY_CANDIDATE'].includes(a.recovery_state)?'warn':'neutral'}">${esc(a.recovery_state||'—')}</span></td><td>${esc(a.strategy||'—')}</td><td>${esc(a.created_at||'—')}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">No recovery events recorded.</td></tr>';}catch(e){const summary=$('#agentRecoverySummary');if(summary)summary.textContent='Recovery history unavailable; no fallback state substituted.'}}

async function refreshAgentExecutionAttempts(){try{const x=await api('/api/platform/admin/agentic-control/execution?limit=25');const rows=x.attempts||[];const body=$('#agentExecutionRows');const summary=$('#agentExecutionSummary');if(summary)summary.textContent=rows.length?`${rows.length} governed execution attempt${rows.length===1?'':'s'} · verification remains explicit and separate from dispatch.`:'No governed execution attempts recorded.';if(body)body.innerHTML=rows.map(a=>`<tr><td>${esc(a.mission_id??'—')}</td><td><b>${esc(a.action_code||'—')}</b></td><td><span class="pill ${['SUCCEEDED','VERIFIED','RECOVERED'].includes(a.status)?'ok':['UNKNOWN','RECOVERY_REQUIRED'].includes(a.status)?'warn':'neutral'}">${esc(a.status||'—')}</span></td><td>${esc(a.verification_status||'—')}</td><td>${esc(a.decision_id||'—')}</td><td>${esc(a.created_at||'—')}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">No governed execution attempts recorded.</td></tr>';}catch(e){const summary=$('#agentExecutionSummary');if(summary)summary.textContent='Execution history unavailable; no fallback state substituted.'}}


document.addEventListener('DOMContentLoaded',()=>{document.getElementById('productionReadiness')?.addEventListener('click',checkProductionReadiness);document.getElementById('productionRefresh')?.addEventListener('click',refreshProductionEvents);});
